package com.supportsphere.model; import java.time.*; public class AssistanceRequest { private int requestId,requesterId; private String taskType,description,area,city,landmark,cancellationReason,volunteerName; private Urgency urgency; private LocalDate preferredDate; private LocalTime startTime,endTime; private RequestStatus status; public int getRequestId(){return requestId;} public void setRequestId(int v){requestId=v;} public int getRequesterId(){return requesterId;} public void setRequesterId(int v){requesterId=v;} public String getTaskType(){return taskType;} public void setTaskType(String v){taskType=v;} public String getDescription(){return description;} public void setDescription(String v){description=v;} public String getArea(){return area;} public void setArea(String v){area=v;} public String getCity(){return city;} public void setCity(String v){city=v;} public String getLandmark(){return landmark;} public void setLandmark(String v){landmark=v;} public Urgency getUrgency(){return urgency;} public void setUrgency(Urgency v){urgency=v;} public LocalDate getPreferredDate(){return preferredDate;} public void setPreferredDate(LocalDate v){preferredDate=v;} public LocalTime getStartTime(){return startTime;} public void setStartTime(LocalTime v){startTime=v;} public LocalTime getEndTime(){return endTime;} public void setEndTime(LocalTime v){endTime=v;} public RequestStatus getStatus(){return status;} public void setStatus(RequestStatus v){status=v;} public String getCancellationReason(){return cancellationReason;} public void setCancellationReason(String v){cancellationReason=v;} public String getVolunteerName(){return volunteerName;} public void setVolunteerName(String v){volunteerName=v;} public String getLocationLabel(){return area+", "+city;} }
